#include <assert.h>
#include <stdio.h>
#include <stdlib.h>

#include <nvpl_tensor.h>

#define HANDLE_ERROR(x)                                           \
    {                                                             \
        const nvpltensorStatus_t err = x;                         \
        if (err != NVPLTENSOR_STATUS_SUCCESS)                     \
        {                                                         \
            printf("Error: %s\n", nvpltensorGetErrorString(err)); \
            exit(-1);                                             \
        }                                                         \
    };

int main()
{
    typedef float floatTypeA;
    typedef float floatTypeB;
    typedef float floatTypeC;
    typedef float floatTypeCompute;

    nvpltensorDataType_t typeA = NVPLTENSOR_R_32F;
    nvpltensorDataType_t typeB = NVPLTENSOR_R_32F;
    nvpltensorDataType_t typeC = NVPLTENSOR_R_32F;
    nvpltensorComputeDescriptor_t const descCompute = NVPLTENSOR_COMPUTE_DESC_32F;

    uint32_t const numThreads = 4;

    /**********************
     * Computing: C_{0,2,1,3} = alpha * A_{0,4,5,1} B_{2,5,3,4} + beta * C_{0,2,1,3}
     **********************/

    floatTypeCompute alpha = (floatTypeCompute) 1.1f;
    floatTypeCompute beta = (floatTypeCompute) 0.f;

    int32_t modeC[] = {0, 2, 1, 3};
    int32_t modeA[] = {0, 4, 5, 1};
    int32_t modeB[] = {2, 5, 3, 4};
    enum { nmodeA = 4 };
    enum { nmodeB = 4 };
    enum { nmodeC = 4 };

    int64_t extent[] = {6, 6, 6, 4, 4, 4};

    int64_t extentC[nmodeC];
    for (int i = 0; i < nmodeC; ++i)
    {
        extentC[i] = extent[modeC[i]];
    }
    int64_t extentA[nmodeA];
    for (int i = 0; i < nmodeA; ++i)
    {
        extentA[i] = extent[modeA[i]];
    }
    int64_t extentB[nmodeB];
    for (int i = 0; i < nmodeB; ++i)
    {
        extentB[i] = extent[modeB[i]];
    }

    /**********************
     * Allocating data
     **********************/

    int64_t elementsA = 1;
    for (int i = 0; i < nmodeA; ++i)
    {
        elementsA *= extentA[i];
    }
    int64_t elementsB = 1;
    for (int i = 0; i < nmodeB; ++i)
    {
        elementsB *= extentB[i];
    }
    int64_t elementsC = 1;
    for (int i = 0; i < nmodeC; ++i)
    {
        elementsC *= extentC[i];
    }

    int64_t sizeA = sizeof(floatTypeA) * elementsA;
    int64_t sizeB = sizeof(floatTypeB) * elementsB;
    int64_t sizeC = sizeof(floatTypeC) * elementsC;

    uint32_t const kAlignment = 128;  // Alignment of the pointers (bytes)

    floatTypeA* A = aligned_alloc(kAlignment, sizeA);
    floatTypeB* B = aligned_alloc(kAlignment, sizeB);
    floatTypeC* C = aligned_alloc(kAlignment, sizeC);

    if (A == NULL || B == NULL || C == NULL)
    {
        printf("Error: allocation of tensor memory.\n");
        return -1;
    }

    /*******************
     * Initialize data
     *******************/

    for (int64_t i = 0; i < elementsA; i++)
        A[i] = (((floatTypeA) (rand() / RAND_MAX)) - 0.5) * 100;
    for (int64_t i = 0; i < elementsB; i++)
        B[i] = (((floatTypeB) (rand() / RAND_MAX)) - 0.5) * 100;
    for (int64_t i = 0; i < elementsC; i++)
        C[i] = (((floatTypeC) (rand() / RAND_MAX)) - 0.5) * 100;

    /*************************
     * nvplTENSOR
     *************************/

    /*************************
     * Create nvplTENSOR handle
     *************************/

    nvpltensorHandle_t handle;
    HANDLE_ERROR(nvpltensorCreate(&handle));

    /**********************
     * Set numbers of threads that nvplTensor can use
     **********************/
    HANDLE_ERROR(nvpltensorSetNumThreads(handle, numThreads));

    /**********************
     * Create Tensor Descriptors
     **********************/

    nvpltensorTensorDescriptor_t descA;
    HANDLE_ERROR(nvpltensorCreateTensorDescriptor(handle, &descA, nmodeA, extentA, NULL, /*stride*/
                                                  typeA, kAlignment));

    nvpltensorTensorDescriptor_t descB;
    HANDLE_ERROR(nvpltensorCreateTensorDescriptor(handle, &descB, nmodeB, extentB, NULL, /*stride*/
                                                  typeB, kAlignment));

    nvpltensorTensorDescriptor_t descC;
    HANDLE_ERROR(nvpltensorCreateTensorDescriptor(handle, &descC, nmodeC, extentC, NULL, /*stride*/
                                                  typeC, kAlignment));

    /*******************************
     * Create Contraction Descriptor
     *******************************/

    nvpltensorOperationDescriptor_t desc;
    HANDLE_ERROR(nvpltensorCreateContraction(handle, &desc, descA, modeA, /* unary operator A*/ NVPLTENSOR_OP_IDENTITY,
                                             descB, modeB, /* unary operator B*/ NVPLTENSOR_OP_IDENTITY, descC, modeC,
                                             /* unary operator C*/ NVPLTENSOR_OP_IDENTITY, descC, modeC, descCompute));

    /*****************************
     * Optional (but recommended): ensure that the scalar type is correct.
     *****************************/

    nvpltensorDataType_t scalarType;
    HANDLE_ERROR(nvpltensorOperationDescriptorGetAttribute(handle, desc, NVPLTENSOR_OPERATION_DESCRIPTOR_SCALAR_TYPE,
                                                           (void*) &scalarType, sizeof(scalarType)));

    assert(scalarType == NVPLTENSOR_R_32F);

    /**************************
     * Set the algorithm to use
     ***************************/

    nvpltensorAlgo_t const algo = NVPLTENSOR_ALGO_DEFAULT;

    nvpltensorPlanPreference_t planPref;
    HANDLE_ERROR(nvpltensorCreatePlanPreference(handle, &planPref, algo, NVPLTENSOR_JIT_MODE_NONE));

    /**********************
     * Query workspace estimate
     **********************/

    uint64_t workspaceSizeEstimate = 0;
    nvpltensorWorksizePreference_t const workspacePref = NVPLTENSOR_WORKSPACE_DEFAULT;
    HANDLE_ERROR(nvpltensorEstimateWorkspaceSize(handle, desc, planPref, workspacePref, &workspaceSizeEstimate));

    /**************************
     * Create Contraction Plan
     **************************/

    nvpltensorPlan_t plan;
    HANDLE_ERROR(nvpltensorCreatePlan(handle, &plan, desc, planPref, workspaceSizeEstimate));

    /**************************
     * Optional: Query information about the created plan
     **************************/

    // query actually used workspace
    uint64_t actualWorkspaceSize = 0;
    HANDLE_ERROR(nvpltensorPlanGetAttribute(handle, plan, NVPLTENSOR_PLAN_REQUIRED_WORKSPACE, &actualWorkspaceSize,
                                            sizeof(actualWorkspaceSize)));

    // At this point the user knows exactly how much memory is need by the operation and
    // only the smaller actual workspace needs to be allocated
    assert(actualWorkspaceSize <= workspaceSizeEstimate);
    actualWorkspaceSize += 256;

    void* work = NULL;
    if (actualWorkspaceSize > 0)
    {
        work = aligned_alloc(kAlignment, actualWorkspaceSize);
    }

    /**********************
     * Execute
     **********************/

    HANDLE_ERROR(
        nvpltensorContract(handle, plan, (void*) &alpha, A, B, (void*) &beta, C, C, work, actualWorkspaceSize));

    /*************************/

    HANDLE_ERROR(nvpltensorDestroy(handle));
    HANDLE_ERROR(nvpltensorDestroyPlan(plan));
    HANDLE_ERROR(nvpltensorDestroyOperationDescriptor(desc));
    HANDLE_ERROR(nvpltensorDestroyTensorDescriptor(descA));
    HANDLE_ERROR(nvpltensorDestroyTensorDescriptor(descB));
    HANDLE_ERROR(nvpltensorDestroyTensorDescriptor(descC));

    if (A)
        free(A);
    if (B)
        free(B);
    if (C)
        free(C);
    if (work)
        free(work);
    return 0;
}

#include <vector>
#include <nvpl_fftw.h>
#include "common.h"

constexpr unsigned howmany = 10;
constexpr unsigned fft_size = 4;
constexpr double   seconds = 10;
constexpr int      fftw_wisdom_success = 1; // https://www.fftw.org/fftw3_doc/Wisdom-Import.html
                                            // The return value of import wisdom APIs is 1 if the wisdom was read successfully and 0 otherwise.

int run_api_test() {

    std::vector<std::complex<double>> inout(howmany*fft_size);
    fftwf_complex *inpout_data = reinterpret_cast<fftwf_complex*>(inout.data() );

    // get version
    std::cout << "NVPL FFT version " << nvpl_fft_get_version() << std::endl;

    // wisdom from system
    int status = fftw_import_system_wisdom();
    if (status != fftw_wisdom_success) {
        std::cout << "fftw_import_system_wisdom: FAILED" << std::endl;
        return 1;
    }

    fftw_plan plan = fftwf_plan_dft_1d(fft_size, inpout_data, inpout_data, FFTW_FORWARD, FFTW_ESTIMATE);

    // wisdom to/from file
    FILE *out_fptr = fopen("wisdom_file.txt", "w");
    if(out_fptr == nullptr) {
        std::cout << "file open FAILED " << std::endl;
        return 1;
    }
    fftw_export_wisdom_to_file(out_fptr);
    fclose(out_fptr);
    std::cout << "fftw_export_wisdom_to_file: PASSED" << std::endl;

    FILE *in_fptr = fopen("wisdom_file.txt", "r");
    if(in_fptr == nullptr) {
        std::cout << "file open FAILED " << std::endl;
        return 1;
    }
    status = fftw_import_wisdom_from_file(in_fptr);
    if (status != fftw_wisdom_success) {
        std::cout << "fftw_import_wisdom_from_file: FAILED" << std::endl;
        return 1;
    }
    fclose(in_fptr);
    std::cout << "fftw_import_wisdom_from_file: PASSED" << std::endl;

    // wisdom to/from string
    char* wisdom_str = fftw_export_wisdom_to_string();
    if(wisdom_str == nullptr) {
        std::cout << "fftw_export_wisdom_to_string: FAILED" << std::endl;
        return 1;
    }
    std::cout << "fftw_export_wisdom_to_string: " << wisdom_str << " PASSED" << std::endl;

    status = fftw_import_wisdom_from_string(wisdom_str);
    if (status != fftw_wisdom_success) {
        std::cout << "fftw_import_wisdom_from_string: FAILED" << std::endl;
        return 1;
    }
    std::cout << "fftw_import_wisdom_from_string: PASSED" << std::endl;
    free(wisdom_str);

    // print plan
    fftw_print_plan(plan);
    std::cout << "fftw_print_plan: PASSED" << std::endl;

    // set timelimit
    fftw_set_timelimit(seconds);
    std::cout << "fftw_set_timelimit: PASSED" << std::endl;

    // cost
    double cost = fftw_cost(plan);
    std::cout << "fftw_cost: cost " << cost << " PASSED" << std::endl;

    // flops
    double add = 0.0, mul = 0.0, fma = 0.0;
    fftw_flops(plan, &add, &mul, &fma);
    std::cout << "fftw_flops: add " << add << ", mul " << mul  << ", fma " << fma << " PASSED" << std::endl;

    fftw_destroy_plan(plan);

    return 0;
}

int main(int argc, [[maybe_unused]] char *argv[]) {
    if (argc < 1) {
        std::cout<<"Usage: ./auxiliary_apis_example\n"<<std::endl;
        return EXIT_FAILURE;
    }
    return run_api_test();
}

#include <vector>
#include <array>
#include <thread>
#include <nvpl_fftw.h>
#include <cassert>
#include "common.h"

void initialize_data(std::vector<std::complex<float>>& c2c_in, std::vector<std::complex<float>>& c2c_inout,
                     std::vector<std::complex<float>>& c2r_in, std::vector<float>& c2r_inout,
                     std::vector<float>& r2c_in, std::vector<float>& r2c_inout) {
    // C2C
    size_t i = 0;
    for (auto& v: c2c_in) {
        v = {(float)i, -(float)i};
        i++;
    }
    i = 0;
    for (auto& v: c2c_inout) {
        v = {(float)i, -(float)i};
        i++;
    }

    // C2R
    i = 0;
    for (auto& v: c2r_in) {
        v = {(float)i, -(float)i};
        i++;
    }
    i = 0;
    for (auto& v: c2r_inout) {
        v = i;
        i++;
    }

    // R2C
    i = 0;
    for (auto& v: r2c_in) {
        v = i;
        i++;
    }
    i = 0;
    for (auto& v: r2c_inout) {
        v = i;
        i++;
    }
}

void print_results(const std::string& api_cat,
                   const std::vector<std::complex<float>>& c2c_out, const std::vector<std::complex<float>>& c2c_inout,
                   const std::vector<float>& c2r_out              , const std::vector<float>& c2r_inout,
                   const std::vector<std::complex<float>>& r2c_out, const std::vector<float>& r2c_inout) {
    std::cout << api_cat << " C2C OOP: ";
    for (const auto& v: c2c_out) {
        std::cout << v << " ";
    }
    std::cout << "\n";

    std::cout << api_cat << " C2C IP : ";
    for (const auto& v: c2c_inout) {
        std::cout << v << " ";
    }
    std::cout << "\n";

    std::cout << api_cat << " C2R OOP: ";
    for (const auto& v: c2r_out) {
        std::cout << v << " ";
    }
    std::cout << "\n";

    std::cout << api_cat << " C2R IP : ";
    for (const auto& v: c2r_inout) {
        std::cout << v << " ";
    }
    std::cout << "\n";

    std::cout << api_cat << " R2C OOP: ";
    for (const auto& v: r2c_out) {
        std::cout << v << " ";
    }
    std::cout << "\n";

    std::cout << api_cat << " R2C IP : ";
    for (const auto& v: r2c_inout) {
        std::cout << v << " ";
    }
    std::cout << "\n";
}

void run_simple_api_test(const std::vector<int>& n) {

    const int howmany = 1;
    const int c2c_complex_elems     = get_product<int>(n.begin(),   n.end());
    const int c2r_r2c_real_elems    = get_product<int>(n.begin(),   n.end());
    const int c2r_r2c_complex_elems = get_product<int>(n.begin(), --n.end()) * (n.back() / 2 + 1);

    const int c2r_idist     =     c2r_r2c_complex_elems;
    const int c2r_ip_odist  = 2 * c2r_r2c_complex_elems;
    const int c2r_oop_odist =        c2r_r2c_real_elems;
    const int r2c_odist     =     c2r_r2c_complex_elems;
    const int r2c_ip_idist  = 2 * c2r_r2c_complex_elems;
    const int r2c_oop_idist =        c2r_r2c_real_elems;
    const int c2c_idist     =         c2c_complex_elems;
    const int c2c_odist     =         c2c_complex_elems;

    std::vector<std::complex<float>>  c2c_in(howmany * c2c_idist    , {0, 0});
    std::vector<std::complex<float>> c2c_out(howmany * c2c_odist    , {0, 0});
    std::vector<float>                r2c_in(howmany * r2c_oop_idist,      0);
    std::vector<std::complex<float>> r2c_out(howmany * r2c_odist    , {0, 0});
    std::vector<std::complex<float>>  c2r_in(howmany * c2r_idist    , {0, 0});
    std::vector<float>               c2r_out(howmany * c2r_oop_odist,      0);

    std::vector<std::complex<float>> c2c_inout(std::max(howmany * c2c_idist   , howmany * c2c_odist)   , {0, 0});
    std::vector<float>               r2c_inout(std::max(howmany * r2c_ip_idist, howmany * r2c_odist)   , 0);
    std::vector<float>               c2r_inout(std::max(howmany * c2r_idist   , howmany * c2r_ip_odist), 0);

    fftwf_plan plan_c2c_oop, plan_c2c_inplace, plan_c2r_oop, plan_c2r_inplace, plan_r2c_oop, plan_r2c_inplace;

    plan_c2c_oop     = fftwf_plan_dft(    n.size(), n.data(), reinterpret_cast<fftwf_complex*>(   c2c_in.data()),   reinterpret_cast<fftwf_complex*>(c2c_out.data()), FFTW_FORWARD, FFTW_ESTIMATE); // out-of-place
    plan_c2c_inplace = fftwf_plan_dft(    n.size(), n.data(), reinterpret_cast<fftwf_complex*>(c2c_inout.data()), reinterpret_cast<fftwf_complex*>(c2c_inout.data()), FFTW_FORWARD, FFTW_ESTIMATE); // in-place
    plan_c2r_oop     = fftwf_plan_dft_c2r(n.size(), n.data(), reinterpret_cast<fftwf_complex*>(   c2r_in.data()),                                     c2r_out.data(), FFTW_MEASURE); // out-of-place
    plan_c2r_inplace = fftwf_plan_dft_c2r(n.size(), n.data(), reinterpret_cast<fftwf_complex*>(c2r_inout.data()),                                   c2r_inout.data(), FFTW_MEASURE); // in-place
    plan_r2c_oop     = fftwf_plan_dft_r2c(n.size(), n.data(),                                      r2c_in.data(),   reinterpret_cast<fftwf_complex*>(r2c_out.data()), FFTW_MEASURE); // out-of-place
    plan_r2c_inplace = fftwf_plan_dft_r2c(n.size(), n.data(),                                   r2c_inout.data(), reinterpret_cast<fftwf_complex*>(r2c_inout.data()), FFTW_MEASURE); // in-place

    initialize_data(c2c_in, c2c_inout, c2r_in, c2r_inout, r2c_in, r2c_inout);

    fftwf_execute(plan_c2c_oop);
    fftwf_execute(plan_c2c_inplace);
    fftwf_execute(plan_c2r_oop);
    fftwf_execute(plan_c2r_inplace);
    fftwf_execute(plan_r2c_oop);
    fftwf_execute(plan_r2c_inplace);

    print_results("SIMPLE", c2c_out, c2c_inout, c2r_out, c2r_inout, r2c_out, r2c_inout);

    /* Free resources */
    fftwf_destroy_plan(plan_c2c_inplace);
    fftwf_destroy_plan(plan_c2c_oop);
    fftwf_destroy_plan(plan_c2r_inplace);
    fftwf_destroy_plan(plan_c2r_oop);
    fftwf_destroy_plan(plan_r2c_inplace);
    fftwf_destroy_plan(plan_r2c_oop);

    fftwf_cleanup();
}

void run_many_api_test(const std::vector<int>& n) {

    const int howmany = 1;
    const int istride = 2, ostride = istride;
    const int c2c_complex_elems     = get_product<int>(n.begin(),   n.end());
    const int c2r_r2c_real_elems    = get_product<int>(n.begin(),   n.end());
    const int c2r_r2c_complex_elems = get_product<int>(n.begin(), --n.end()) * (n.back() / 2 + 1);

    const int c2r_idist     =     c2r_r2c_complex_elems * istride;
    const int c2r_ip_odist  = 2 * c2r_r2c_complex_elems * ostride;
    const int c2r_oop_odist =        c2r_r2c_real_elems * ostride;
    const int r2c_odist     =     c2r_r2c_complex_elems * ostride;
    const int r2c_ip_idist  = 2 * c2r_r2c_complex_elems * istride;
    const int r2c_oop_idist =        c2r_r2c_real_elems * istride;
    const int c2c_idist     =         c2c_complex_elems * istride;
    const int c2c_odist     =         c2c_complex_elems * ostride;

    std::vector<std::complex<float>>  c2c_in(howmany * c2c_idist    , {0, 0});
    std::vector<std::complex<float>> c2c_out(howmany * c2c_odist    , {0, 0});
    std::vector<float>                r2c_in(howmany * r2c_oop_idist,      0);
    std::vector<std::complex<float>> r2c_out(howmany * r2c_odist    , {0, 0});
    std::vector<std::complex<float>>  c2r_in(howmany * c2r_idist    , {0, 0});
    std::vector<float>               c2r_out(howmany * c2r_oop_odist,      0);

    std::vector<std::complex<float>> c2c_inout(std::max(howmany * c2c_idist   , howmany * c2c_odist)   , {0, 0});
    std::vector<float>               r2c_inout(std::max(howmany * r2c_ip_idist, howmany * r2c_odist)   , 0);
    std::vector<float>               c2r_inout(std::max(howmany * c2r_idist   , howmany * c2r_ip_odist), 0);

    fftwf_plan plan_c2c_oop, plan_c2c_inplace, plan_c2r_oop, plan_c2r_inplace, plan_r2c_oop, plan_r2c_inplace;

    plan_c2c_oop     = fftwf_plan_many_dft(    n.size(), n.data(), howmany, reinterpret_cast<fftwf_complex*>(   c2c_in.data()), nullptr, istride,     c2c_idist,   reinterpret_cast<fftwf_complex*>(c2c_out.data()), nullptr, ostride,     c2c_odist, FFTW_FORWARD, FFTW_ESTIMATE); // out-of-place
    plan_c2c_inplace = fftwf_plan_many_dft(    n.size(), n.data(), howmany, reinterpret_cast<fftwf_complex*>(c2c_inout.data()), nullptr, istride,     c2c_idist, reinterpret_cast<fftwf_complex*>(c2c_inout.data()), nullptr, ostride,     c2c_odist, FFTW_FORWARD, FFTW_ESTIMATE); // in-place
    plan_c2r_oop     = fftwf_plan_many_dft_c2r(n.size(), n.data(), howmany, reinterpret_cast<fftwf_complex*>(   c2r_in.data()), nullptr, istride,     c2r_idist,                                     c2r_out.data(), nullptr, ostride, c2r_oop_odist, FFTW_MEASURE); // out-of-place
    plan_c2r_inplace = fftwf_plan_many_dft_c2r(n.size(), n.data(), howmany, reinterpret_cast<fftwf_complex*>(c2r_inout.data()), nullptr, istride,     c2r_idist,                                   c2r_inout.data(), nullptr, ostride,  c2r_ip_odist, FFTW_MEASURE); // in-place
    plan_r2c_oop     = fftwf_plan_many_dft_r2c(n.size(), n.data(), howmany,                                      r2c_in.data(), nullptr, ostride, r2c_oop_idist,   reinterpret_cast<fftwf_complex*>(r2c_out.data()), nullptr, istride,     r2c_odist, FFTW_MEASURE); // out-of-place
    plan_r2c_inplace = fftwf_plan_many_dft_r2c(n.size(), n.data(), howmany,                                   r2c_inout.data(), nullptr, ostride,  r2c_ip_idist, reinterpret_cast<fftwf_complex*>(r2c_inout.data()), nullptr, istride,     r2c_odist, FFTW_MEASURE); // in-place

    initialize_data(c2c_in, c2c_inout, c2r_in, c2r_inout, r2c_in, r2c_inout);

    fftwf_execute(plan_c2c_oop);
    fftwf_execute(plan_c2c_inplace);
    fftwf_execute(plan_c2r_oop);
    fftwf_execute(plan_c2r_inplace);
    fftwf_execute(plan_r2c_oop);
    fftwf_execute(plan_r2c_inplace);

    print_results("MANY", c2c_out, c2c_inout, c2r_out, c2r_inout, r2c_out, r2c_inout);

    /* Free resources */
    fftwf_destroy_plan(plan_c2c_inplace);
    fftwf_destroy_plan(plan_c2c_oop);
    fftwf_destroy_plan(plan_c2r_inplace);
    fftwf_destroy_plan(plan_c2r_oop);
    fftwf_destroy_plan(plan_r2c_inplace);
    fftwf_destroy_plan(plan_r2c_oop);

    fftwf_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        std::cout<<"Usage: ./c2c_c2r_r2c_single_apis_example NX [NY [NZ]]\n"
                 <<"Arguments:\n"
                 <<"\tNX: The transform size in x (outermost) dimension.\n"
